let table = {{workflowparams:allData}};

if(table.sales_return_no_type !== -9999 && (
  !table.sales_return_no|| table.sales_return_no === null || table.sales_return_no === ''
)) {
  table.sales_return_no = 'draft'
}

return { table };

let table = {{workflowparams:allData}};

if (
  table.sales_return_no_type !== -9999 &&
  (!table.sales_return_no ||
    table.sales_return_no === null ||
    table.sales_return_no === "" ||
    table.previous_status == "Draft")
) {
  table.sales_return_no = 'issued'
}

return { table };

const entry = {{node:code_node_i1NUMscC.data.table}};

// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// table_sr is a tree: an item bundle is ONE row with the bundle's items under
// `children`. Each of those items is a goods delivery line in its own right --
// its own gd_line_id, its own returned quantity, its own invoice line -- so a
// walk that stops at the top level asks for none of them.
//
// Everything downstream keys off this list: the GD lines fetched for the
// returnable check and for the return-quantity sync, and the SI lines the
// credit note is built from. Leave a bundle's items out here and every one of
// those steps skips them silently.
// ==========================================================================
const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);
const flattenSrRows = (rows) =>
  (rows || []).flatMap((row) => [row, ...childrenOf(row)]);

const gdIDs = flattenSrRows(entry.table_sr).map((item) => item.gd_line_id);

return { gdIDs }

const entry = {{node:code_node_i1NUMscC.data.table}};
const gdLineItemList = {{node:search_node_OfTEOTAo.data.data}};

const roundQty = (value) => Math.round((parseFloat(value) || 0) * 1000) / 1000;

// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// table_sr is a tree: an item bundle is ONE row with the bundle's items under
// `children`. Those items are delivery lines like any other and each has its
// own returnable quantity, so the check below is taken over every line, not
// just the top level. The bundle row is checked too: the delivery has a bundle
// line of its own and it is returned against in bundles.
//
// A bundle is also returned whole or not at all. Every item under it carries
// the quantity the bundle row fixed for it -- returning 2 of item A against 1
// of item B, when one bundle holds one of each, is not a bundle. The form is
// the only thing enforcing that, so anything reaching this workflow by another
// route (an API call, a stale page) would otherwise be saved as it stands.
// ==========================================================================
const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);
const isBundleParentRow = (row) =>
  Boolean(row.item_bundle_id) && !row.material_id;

// Every line with the number it is shown by. A bundle's items are numbered
// inside their bundle -- #1, #1-1, #1-2, #2 -- so a message names a row the
// user can actually find.
const labelledRows = [];

(entry.table_sr || []).forEach((row, index) => {
  labelledRows.push({ row: row, label: `#${index + 1}` });

  childrenOf(row).forEach((child, childIndex) => {
    labelledRows.push({ row: child, label: `#${index + 1}-${childIndex + 1}` });
  });
});

let invalidReturnQty = [];

for (const line of labelledRows) {
  const item = line.row;
  const gdLine = gdLineItemList.find((gd) => gd.id === item.gd_line_id);
  if (gdLine) {
    const maxReturnableQty = (gdLine.gd_qty || 0) - (gdLine.return_qty || 0);
    if ((item.expected_return_qty || 0) > maxReturnableQty) {
      invalidReturnQty.push(line.label);
    }
  }
}

// The rate is worked out the same way the form works it out: what the delivery
// holds of this item per bundle, applied to the number of bundles being
// returned, and never past what the item itself still has outstanding.
const bundleRatioProblem = (parent, child) => {
  const bundleDelivered = roundQty(parent.good_delivery_qty);

  // Nothing to derive a rate from -- leave the line alone rather than guess.
  if (bundleDelivered <= 0) return null;

  const perBundle =
    (parseFloat(child.good_delivery_qty) || 0) / bundleDelivered;
  const scaled = roundQty(
    perBundle * (parseFloat(parent.expected_return_qty) || 0),
  );
  const returnable = roundQty(child.to_returned_qty);
  const expected = scaled > returnable ? returnable : scaled;
  const actual = roundQty(child.expected_return_qty);

  return Math.abs(actual - expected) > 0.001
    ? { expected: expected, actual: actual }
    : null;
};

const bundleOffenders = [];

(entry.table_sr || []).forEach((row, index) => {
  if (!isBundleParentRow(row)) return;

  childrenOf(row).forEach((child, childIndex) => {
    const ratio = bundleRatioProblem(row, child);
    if (!ratio) return;

    const label =
      child.material_name || child.material_desc || child.material_id || "Unknown";

    bundleOffenders.push(
      `#${index + 1}-${childIndex + 1} ${label}: expected ${ratio.expected}, got ${ratio.actual}`,
    );
  });
});

const parts = [];

if (invalidReturnQty.length > 0) {
  parts.push(
    `Line${invalidReturnQty.length > 1 ? "s" : ""} ${invalidReturnQty.join(
        ", ",
      )} ha${
        invalidReturnQty.length > 1 ? "ve" : "s"
      } an expected return quantity exceeding the maximum returnable quantity.`
  );
}

if (bundleOffenders.length > 0) {
  parts.push(
    "Item bundle quantities must stay in proportion to the number of bundles:\n" +
      bundleOffenders.join("\n") +
      "\nReturn an item bundle by its bundle line - its items follow from it and cannot be returned on their own.",
  );
}

if(parts.length > 0) {
  return {
    status: 'Failed',
    message: parts.join("\n\n")
  }
}

return {
  status: 'Success',
  message: ''
}

let entry = {{node:code_node_i1NUMscC.data.table}};

// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// table_sr is a tree: an item bundle is ONE row with the bundle's items under
// `children`.
//
// The quantity checks below stay on the TOP LEVEL deliberately. A bundle is one
// line to the user and its quantity is the number of bundles; its items are not
// rows they can type into, and an item whose share of the bundle rounds to zero
// is not something they can act on. Dropping a zero-quantity bundle row takes
// its items with it, which is what returning nothing of a bundle means.
//
// The header roll-ups are different: a bundle's items carry their own sales
// order line, and it is not always the bundle's, so those are taken over every
// line in the tree.
// ==========================================================================
const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);
const flattenSrRows = (rows) =>
  (rows || []).flatMap((row) => [row, ...childrenOf(row)]);

// Check total return qty
const totalQuantity = entry.table_sr.reduce((sum, item) => {
    const { expected_return_qty } = item;
    return sum + (expected_return_qty || 0);
  }, 0);

if(totalQuantity <= 0){
  return {
    status: 'Failed',
    code: '403',
    message: 'Total return quantity is 0.',
    entry
  }
}

// Check line return qty
let zeroQtyArray = [];
for(const [index, sr] of entry.table_sr.entries()) {
  if (!sr.expected_return_qty || sr.expected_return_qty <= 0) {
    zeroQtyArray.push(`#${index + 1}`);
  }
}

if(zeroQtyArray.length > 0) {
  if(entry.filter_sr == 'Yes') {
    entry.table_sr = entry.table_sr.filter(
      (item) => item.expected_return_qty > 0,
    );

    if(entry.table_sr.length === 0) {
      return {
        status: 'Failed',
        code: '405',
        message: 'All Return Quantity must not be 0. Please add at least one item with return quantity > 0.',
        entry
      }
    }

    let salesOrderNumber = [];
    let soId = [];
    let goodsDeliveryNumber = [];
    let gdId = [];
    let handlingUnitNumber = [];
    for (const sr of flattenSrRows(entry.table_sr)) {
      gdId.push(sr.gd_id);
      goodsDeliveryNumber.push(sr.gd_number);

      soId.push(sr.so_id);
      salesOrderNumber.push(sr.line_so_no);

      // Dropping a row takes its handling units with it, so the header summary
      // is rebuilt from the rows that survived rather than left as it was.
      for (const huNo of (sr.hu_no_display || "").split(", ")) {
        if (huNo) handlingUnitNumber.push(huNo);
      }
    }

    soId = [...new Set(soId)];
    gdId = [...new Set(gdId)];
    salesOrderNumber = [...new Set(salesOrderNumber)];
    goodsDeliveryNumber = [...new Set(goodsDeliveryNumber)];
    handlingUnitNumber = [...new Set(handlingUnitNumber)];

    entry.so_id = soId;
    entry.gd_id = gdId;
    entry.so_no_display = salesOrderNumber.join(", ");
    entry.gd_no_display = goodsDeliveryNumber.join(", ");
    entry.hu_no_display = handlingUnitNumber.join(", ");
  } else {
    return {
      status: 'Failed',
      code: '404',
      message: `Line${zeroQtyArray.length > 1 ? "s" : ""} ${zeroQtyArray.join(", ")} ha${
        zeroQtyArray.length > 1 ? "ve" : "s"
      } a zero return quantity, which may prevent processing.\nIf you proceed, it will delete the row with 0 return quantity. \nWould you like to proceed?`,
      entry
    }
  }
}

// A delivery that shipped in a handling unit should carry that unit onto the
// return, so receiving knows which container to load the stock back into.
// Missing it is a warning rather than an error: the user confirms, and that
// confirmation comes back as filter_sr_hu. Checked last, so it is asked about
// the rows that survived the quantity checks above rather than the rows the
// user started with.
const hasHuData = (raw) => {
  if (!raw) return false;
  if (Array.isArray(raw)) return raw.length > 0;

  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) && parsed.length > 0;
  } catch (error) {
    return false;
  }
};

// Only on a NEW return. A sales return raised before handling units were captured
// carries no temp_hu_data of its own, so editing one would warn every time about
// something the user cannot fix except by removing the line and re-adding it.
// page_status is the same discriminator the add/update fork already uses.
if (entry.filter_sr_hu != 'Yes' && entry.page_status == 'Add') {
  const gdLineItemList = {{node:search_node_OfTEOTAo.data.data}} || [];
  const missingHu = [];

  const checkHu = (line, label) => {
    // A bundle row holds no stock of its own, so it never had a handling unit.
    if (!line.material_id) return;
    if (hasHuData(line.temp_hu_data)) return;

    const gdLine = gdLineItemList.find((gd) => gd.id === line.gd_line_id);
    if (gdLine && hasHuData(gdLine.temp_hu_data)) missingHu.push(label);
  };

  (entry.table_sr || []).forEach((row, index) => {
    checkHu(row, `#${index + 1}`);

    childrenOf(row).forEach((child, childIndex) =>
      checkHu(child, `#${index + 1}-${childIndex + 1}`),
    );
  });

  if (missingHu.length > 0) {
    return {
      status: 'Failed',
      code: '407',
      message: `Line${missingHu.length > 1 ? "s" : ""} ${missingHu.join(", ")} ${
        missingHu.length > 1 ? "were" : "was"
      } delivered in a handling unit, but none was captured on this return.\nReceiving will not be able to put the stock back into its original handling unit.\nWould you like to proceed?`,
      entry
    }
  }
}

return {
  status: 'Success',
  code: '',
  message: '',
  entry
}

let entry = {{workflowparams:allData.sr_status}} === 'Draft' ? {{node:code_node_qFbAnGEH.data.table}} : {{node:code_node_rG74lIOj.data.entry}};

// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// table_sr is a tree: an item bundle is ONE row with the bundle's items under
// `children`. Those items are return lines in their own right and carry the
// same header fields as a top-level line -- they simply are not rows of
// table_sr. Stamping only the top level leaves every one of them without a
// customer, a plant or a line number, and its quantities unformatted.
//
// A bundle's items are numbered inside their bundle -- 1, 1-1, 1-2, 2 -- which
// is the convention the sales invoice already uses. line_index is a text
// column, so the label is safe to store.
// ==========================================================================
const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);

const stampLine = (srLineItem, lineLabel) => ({
  ...srLineItem,
  // Number formatting
  so_quantity: parseFloat(srLineItem.so_quantity?.toFixed(3)) || 0,
  good_delivery_qty: parseFloat(srLineItem.good_delivery_qty?.toFixed(3)) || 0,
  to_returned_qty: parseFloat(srLineItem.to_returned_qty?.toFixed(3)) || 0,
  expected_return_qty: parseFloat(srLineItem.expected_return_qty?.toFixed(3)) || 0,
  received_qty: parseFloat(srLineItem.received_qty?.toFixed(3)) || 0,
  unit_price: parseFloat(srLineItem.unit_price?.toFixed(4)) || 0,
  total_price: parseFloat(srLineItem.total_price?.toFixed(4)) || 0,

  customer_id: entry.customer_id || null,
  plant_id: entry.plant_id || null,
  billing_state_id: entry.billing_address_state || null,
  billing_country_id: entry.billing_address_country || null,
  shipping_state_id: entry.shipping_address_state || null,
  shipping_country_id: entry.shipping_address_country || null,
  line_index: lineLabel,
  agent_id: entry.sales_pic_id,
  area_id: entry.sr_area_id,
});

let updatedLineItem = [];

for(const [index, srLineItem] of entry.table_sr.entries()) {
  // Create a new object with formatted values
  const formattedItem = stampLine(srLineItem, index + 1);

  const kids = childrenOf(srLineItem);

  if (kids.length > 0) {
    formattedItem.children = kids.map((child, childIndex) =>
      stampLine(child, `${index + 1}-${childIndex + 1}`),
    );
  }

  updatedLineItem.push(formattedItem);
}

entry.table_sr = updatedLineItem;

return { entry }

// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// table_sr is a tree: an item bundle is ONE row with the bundle's items under
// `children`. Every per-line step after this one -- the goods delivery sync,
// the credit note conditions, the credit note itself -- has to see those items,
// and none of them should have to know about bundles to do it. So the tree is
// resolved once here and handed on as two views:
//
//   srTree   the tree, which is what the credit note is built from: a bundle is
//            one line there too, with its items beneath it
//   srLines  the same tree flat, bundle rows included -- what anything keyed on
//            a delivery line iterates
//
// The tree comes from the fillback entry rather than from srData, because on
// Add srData is the record the add node echoed back and that echo lists the
// TOP-LEVEL rows only. Reading a bundle's items off it finds nothing. What the
// echo does carry is each saved line's database id, so those are grafted onto
// the entry's tree by the delivery line they were returned against.
// ==========================================================================
const entry = {{node:code_node_9Wk6aEGR.data.entry}};
const pageStatus = {{workflowparams:allData.page_status}};

let srData = pageStatus === 'Add' ? {{node:add_node_aUoxp8ox.data}}[0] : entry;

const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);
const flattenSrRows = (rows) =>
  (rows || []).flatMap((row) => [row, ...childrenOf(row)]);

// Flattened rather than read off the top level, so a bundle's items are picked
// up on any platform version whose echo does carry them.
const savedIdByGdLine = {};

for (const line of flattenSrRows(srData.table_sr)) {
  if (line.gd_line_id && line.id) {
    savedIdByGdLine[String(line.gd_line_id)] = line.id;
  }
}

const graft = (row) => {
  const copy = { ...row };

  if (!copy.id && copy.gd_line_id && savedIdByGdLine[String(copy.gd_line_id)]) {
    copy.id = savedIdByGdLine[String(copy.gd_line_id)];
  }

  const kids = childrenOf(row);
  if (kids.length > 0) copy.children = kids.map(graft);

  return copy;
};

const srTree = (entry.table_sr || []).map(graft);
const srLines = flattenSrRows(srTree);

return { srData, srTree, srLines };

const gdLineItemList = {{node:search_node_OfTEOTAo.data.data}};
// table_sr is a tree: an item bundle is ONE row with the bundle's items under
// `children`. Each item is booked back onto its own goods delivery line, so the
// flat view is what this is matched against -- a lookup over the top level
// alone finds nothing for them and leaves their return quantity untouched.
const srLines = {{node:code_node_qYJ8wTWS.data.srLines}};
let latestGDLineItemList = [];

for(const gdLineItem of gdLineItemList) {
  const returnQty = srLines.find(item => item.gd_line_id === gdLineItem.id)?.expected_return_qty ?? 0;

  const latestReturnQty = parseFloat(returnQty) + parseFloat(gdLineItem.return_qty || 0);

  latestGDLineItemList.push({
    id: gdLineItem.id,
    return_qty: latestReturnQty.toFixed(3),
    sr_status: parseFloat(latestReturnQty) >= parseFloat(gdLineItem.gd_qty || 0) ? "Fully Returned" : "Partially Returned",
  })
}

return { latestGDLineItemList }

const gdList = {{node:search_node_gnlJ7vR5.data.data}};

// The goods delivery stores its bundles the same way this document does: ONE
// row with the bundle's items under `children`. Each of those items carries its
// own delivered and returned quantity, so a walk that stops at the top level
// judges the whole delivery on its bundle lines alone -- and a delivery whose
// bundle line happened to be fully returned reads as Fully Returned while items
// under it are still outstanding.
const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);
const flattenGdRows = (rows) =>
  (rows || []).flatMap((row) => [row, ...childrenOf(row)]);

const latestGDList = gdList.map((item, index) => {
  const updatedGDStatus = flattenGdRows(item.table_gd).some(
    (gdItem) =>
      parseFloat(gdItem.return_qty || 0) < parseFloat(gdItem.gd_qty || 0),
  )
    ? "Partially Returned"
    : "Fully Returned";

  return {
    id: item.id,
    sr_status: updatedGDStatus,
  };
});

return { latestGDList }

const srSetup = {{node:get_node_rx6bgxbr.data.data}} ?? null;

if(!srSetup || !srSetup.id || srSetup.id === '') {
  return {
    createCN: 'No'
  }
} else {
  return {
    createCN: srSetup.auto_cn != 1 || srSetup.trigger_by != 'Sales Return' ? 'No' : 'Yes'
  }
}

const siList = {{node:search_node_3wVLWJqB.data.data}};
const siLineItemList = {{node:search_node_U59iQSEF.data.data}};
// table_sr is a tree: an item bundle is ONE row with the bundle's items under
// `children`. Each item is invoiced on its own SI line, so the conditions below
// are checked over the flat view -- the bundle row included, since the invoice
// carries a bundle line of its own and that is where the money sits.
const srLines = {{node:code_node_qYJ8wTWS.data.srLines}};

// Condition 1: one gd_line_id must map to exactly one SI
const gdLineToSIMap = {};
for (const siLine of siLineItemList) {
  if (!siLine.gd_line_id) continue;
  if (gdLineToSIMap[siLine.gd_line_id]) {
    return {
      status: 'Failed',
      message: `GD is mapped to more than one SI.`
    };
  }
  gdLineToSIMap[siLine.gd_line_id] = siLine.si_id;
}

// Condition 2: one SI must map to exactly one gd_id in srData
const multipleGDSI = siList.filter(si => si.gd_id.length > 1)
if(multipleGDSI.length > 0) {
  return {
    status: 'Failed',
    message: `SI contains more than one GDs.`
  };
}

// Condition 3 & 4: check per SR line
for (const [index, sr] of srLines.entries()) {
  const matchedSILine = siLineItemList.find(line => line.gd_line_id === sr.gd_line_id);
  if (!matchedSILine) {
    return {
      status: 'Failed',
      message: `No matching SI line found for GD Line ID ${sr.gd_line_id}.`
    };
  }

  // Condition 3: invoice_qty must be greater than return qty
  const returnQty = parseFloat(sr?.expected_return_qty) ?? 0;
  if (parseFloat(matchedSILine.invoice_qty) - parseFloat(matchedSILine.credit_qty) < returnQty) {
    return {
      status: 'Failed',
      message: `Invoice quantity (${matchedSILine.invoice_qty}) must be greater than return quantity (${returnQty}).`
    };
  }

  // Condition 4: si_amount must be greater than 0
  if (matchedSILine.si_amount <= 0) {
    return {
      status: 'Failed',
      message: `Invoice line total must be greater than 0.`
    };
  }
}

return {
  status: 'Passed',
  message: ''
};

const formatNumberTo4 = (value) => {
  if (value === null || value === undefined || value === "") return "0.0000";
  return parseFloat(value).toFixed(4);
};

const formatNumberTo3 = (value) => {
  if (value === null || value === undefined || value === "") return "0.000";
  return parseFloat(value).toFixed(3);
};

const roundTo4 = (value) => {
  return Math.round((parseFloat(value) || 0) * 10000) / 10000;
};

const calculateFinalPrice = (total, invoiceQty, creditQty) => {
  const priceForCredit =
    (roundTo4(total) / roundTo4(invoiceQty)) * roundTo4(creditQty);

  return roundTo4(priceForCredit);
};

const sumPrice = (fieldName, cnLineItemList) => {
  return roundTo4(
    cnLineItemList.reduce((total, item) => {
      return roundTo4(total) + roundTo4(item[fieldName]);
    }, 0),
  );
};

const srData = {{node:code_node_qYJ8wTWS.data.srData}};
// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// table_sr is a tree: an item bundle is ONE row with the bundle's items under
// `children`, and the credit note is built the same way -- the bundle is one
// line with its items beneath it, which is the shape the sales invoice already
// has.
//
// The money sits on the BUNDLE line. Its invoice line's amount, discount and
// tax are already the sum of its items, so the header totals are summed over
// the TOP LEVEL only. Counting the items as well credits the bundle twice.
//
// A bundle line is not an item: it has no material and no unit of measure, and
// both are id-typed columns on the credit note. Letting a null through comes
// back as 数据转换BigInt类型失败, so they are blanked instead.
// ==========================================================================
const srTree = {{node:code_node_qYJ8wTWS.data.srTree}};
const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);
const siLineItemList = {{node:search_node_U59iQSEF.data.data}};
const siList = {{node:search_node_3wVLWJqB.data.data}};
const cnDocFormat = {{node:get_node_YkDvO5xI.data.data}};
const customerData = {{node:get_node_vcDlmNfk.data.data}};
const currencyCode = {{node:get_node_0U04xCWm.data.data}};
const shippingAddress = {{node:get_node_vEuXoaDu.data.data}};
const billingAddress = {{node:get_node_Htx4STEq.data.data}};
let cnLineItemList = [];

const buildCNLine = (srLineItem, lineIndex) => {
  const matchedSILineItem = siLineItemList.find(
    (item) => item.gd_line_id === srLineItem.gd_line_id,
  );

  const matchedSI = siList.find(
    (item) => item.id === matchedSILineItem.sales_invoice_id,
  );

  return {
    si_id: matchedSILineItem?.sales_invoice_id || "",
    item_id: srLineItem.material_id || "",
    item_name: srLineItem.material_name,
    uom_id: srLineItem.quantity_uom || "",
    credit_qty: formatNumberTo3(srLineItem.expected_return_qty),
    unit_price: formatNumberTo4(matchedSILineItem.unit_price),
    subtotal:
      roundTo4(srLineItem.expected_return_qty) *
      roundTo4(matchedSILineItem.unit_price),
    discount: roundTo4(matchedSILineItem.si_discount),
    discount_type: matchedSILineItem?.si_discount_uom_id || "",
    discount_amount: calculateFinalPrice(
      matchedSILineItem.discount_amount,
      matchedSILineItem.invoice_qty,
      srLineItem.expected_return_qty,
    ),
    tax_code: matchedSILineItem?.si_tax_rate_id || "",
    tax_percent: matchedSILineItem?.tax_percent || "",
    tax_amount: calculateFinalPrice(
      matchedSILineItem.tax_amount,
      matchedSILineItem.invoice_qty,
      srLineItem.expected_return_qty,
    ),
    total: calculateFinalPrice(
      matchedSILineItem.si_amount,
      matchedSILineItem.invoice_qty,
      srLineItem.expected_return_qty,
    ),
    line_status: "Closed",
    line_index: lineIndex,
    si_line_id: matchedSILineItem?.id || "",
    sr_line_id: srLineItem.id,
    sr_id: srData.sales_return_id,
    plant_id: srData.plant_id,
    customer_id: srData.customer_id,
    tax_inclusive: matchedSILineItem?.si_tax_inclusive || 0,
    invoice_qty: formatNumberTo3(matchedSILineItem.invoice_qty),
    item_desc: srLineItem.material_desc,
    item_bundle_id: srLineItem.item_bundle_id || "",
    si_no: matchedSI?.sales_invoice_no || "",
    more_desc: srLineItem.more_desc,
    available_credit_qty: formatNumberTo3(
      matchedSILineItem.invoice_qty - matchedSILineItem.credit_qty,
    ),
  };
};

// A bundle's items are numbered inside their bundle -- 1, 1-1, 1-2, 2 -- which
// is the convention the sales invoice uses, and they are rows of their bundle
// rather than rows of the credit note.
srTree.forEach((srLineItem, index) => {
  const cnLineItem = buildCNLine(srLineItem, index + 1);

  const kids = childrenOf(srLineItem);

  if (kids.length > 0) {
    cnLineItem.children = kids.map((child, childIndex) =>
      buildCNLine(child, `${index + 1}-${childIndex + 1}`),
    );
  }

  cnLineItemList.push(cnLineItem);
});

const cnData = {
  cn_status: "Completed",
  page_status: "Add",
  acc_integration_type: srData.acc_integration_type,
  organization_id: srData.organization_id,
  previous_status: null,
  plant_id: srData.plant_id,
  customer_id: srData.customer_id,
  currency_code: currencyCode?.currency_code || "",
  cn_no: "issued",
  cn_no_type: cnDocFormat.id,
  cn_date: new Date().toISOString().split("T")[0],
  cn_type: "Return",
  source_type: "Sales Invoice",
  source_id: [...new Set(cnLineItemList.map((item) => item.si_id))],
  source_no: [...new Set(cnLineItemList.map((item) => item.si_no))].join(", "),
  sales_return_id: srData.id,
  total_gross_currency: currencyCode?.currency_code || "",
  total_discount_currency: currencyCode?.currency_code || "",
  total_tax_currency: currencyCode?.currency_code || "",
  total_amount_currency: currencyCode?.currency_code || "",
  total_amount_myr: "MYR",
  subtotal: sumPrice("subtotal", cnLineItemList),
  total_discount: sumPrice("discount_amount", cnLineItemList),
  tax_total: sumPrice("tax_amount", cnLineItemList),
  grand_total: sumPrice("total", cnLineItemList),
  myr_grand_total:
    sumPrice("total", cnLineItemList) *
    roundTo4(currencyCode.currency_buying_rate),
  table_cn: cnLineItemList,
  remark: srData.remark,
  billing_address_name: billingAddress.address_name ?? null,
  billing_address_phone: billingAddress.address_phone ?? null,
  billing_address_line_1: billingAddress.address_line_1 ?? null,
  billing_address_line_2: billingAddress.address_line_2 ?? null,
  billing_address_line_3: billingAddress.address_line_3 ?? null,
  billing_address_line_4: billingAddress.address_line_4 ?? null,
  billing_address_city: billingAddress.address_city ?? null,
  billing_postal_code: billingAddress.address_postal_code ?? null,
  billing_address_state: billingAddress.adddress_state ?? null,
  billing_address_country: billingAddress.address_country_id ?? null,
  billing_attention: billingAddress.address_attention ?? null,
  shipping_address_name: shippingAddress.address_name ?? null,
  shipping_address_phone: shippingAddress.address_phone ?? null,
  shipping_address_line_1: shippingAddress.address_line_1 ?? null,
  shipping_address_line_2: shippingAddress.address_line_2 ?? null,
  shipping_address_line_3: shippingAddress.address_line_3 ?? null,
  shipping_address_line_4: shippingAddress.address_line_4 ?? null,
  shipping_address_city: shippingAddress.address_city ?? null,
  shipping_postal_code: shippingAddress.address_postal_code ?? null,
  shipping_address_country: shippingAddress.address_country_id ?? null,
  shipping_address_state: shippingAddress.adddress_state ?? null,
  shipping_attention: shippingAddress.address_attention ?? null,
  exchange_rate_myr: "MYR",
  exchange_rate_currency: currencyCode?.currency_code || "",
  exchange_rate: currencyCode?.currency_buying_rate || "1.0000",
  cn_billing_address: billingAddress.address ?? null,
  cn_shipping_address: shippingAddress.address ?? null,
  posted_status: "Unposted",
};

return { cnData };
